def transform(grid):
    g = np.array(grid)
    H, W = g.shape
    rows = [y for y in range(H) if (g[y] == g[y, 0]).all()]
    cols = [x for x in range(W) if (g[:, x] == g[0, x]).all()]
    ys = [-1] + rows + [H]
    xs = [-1] + cols + [W]
    boxes = []  # grid of panel boxes by meta position
    for i in range(len(ys) - 1):
        row = []
        for j in range(len(xs) - 1):
            y0, y1 = ys[i] + 1, ys[i + 1] - 1
            x0, x1 = xs[j] + 1, xs[j + 1] - 1
            if y1 >= y0 and x1 >= x0:
                row.append((y0, x0, y1, x1))
        if row:
            boxes.append(row)
    # empty colour = most common colour inside panels
    from collections import Counter
    cnt = Counter()
    for row in boxes:
        for (y0, x0, y1, x1) in row:
            cnt.update(g[y0:y1 + 1, x0:x1 + 1].flatten().tolist())
    empty = cnt.most_common(1)[0][0]
    # colour sets per panel
    sets = {}
    for i, row in enumerate(boxes):
        for j, (y0, x0, y1, x1) in enumerate(row):
            sets[(i, j)] = set(g[y0:y1 + 1, x0:x1 + 1].flatten().tolist()) - {empty}
    n = len(sets)
    key = None
    allc = set().union(*sets.values())
    for c in allc:
        have = [k for k, s in sets.items() if c in s]
        if len(have) == n - 1:
            key = [k for k in sets if c not in sets[k]][0]
            break
    if key is None:
        key = min(sets, key=lambda k: len(sets[k]))
    ky0, kx0, ky1, kx1 = boxes[key[0]][key[1]]
    mp = g[ky0:ky1 + 1, kx0:kx1 + 1]
    out = g.copy()
    for row in boxes:
        for (y0, x0, y1, x1) in row:
            out[y0:y1 + 1, x0:x1 + 1] = empty
    emit(out, "Clear every panel to the empty colour, keeping the divider lines")
    for i, row in enumerate(boxes):
        for j, (y0, x0, y1, x1) in enumerate(row):
            if i < mp.shape[0] and j < mp.shape[1] and mp[i, j] != empty:
                out[y0:y1 + 1, x0:x1 + 1] = mp[i, j]
                emit(out, f"Map cell ({i},{j}) of the odd panel has colour {mp[i,j]}: fill panel ({i},{j}) with it")
    emit(out, "Final: the odd-one-out panel scaled up onto the panel grid")
    return out
